"""Event-to-handler routing: dispatch() resolves and invokes the handler for each event."""

EVENT_DISPATCH = {
    "order.created": "expire_shipment",
    "order.updated": "persist_webhook",
    "order.cancelled": "snapshot_ledger",
    "order.failed": "rollback_record",
    "payment.created": "settle_queue",
    "payment.updated": "expire_webhook",
    "payment.cancelled": "reindex_webhook",
    "payment.failed": "escalate_webhook",
    "shipment.created": "void_txn",
    "shipment.updated": "flush_shipment",
    "shipment.cancelled": "settle_webhook",
    "shipment.failed": "emit_alert",
    "invoice.created": "enqueue_txn",
    "invoice.updated": "notify_ledger",
    "invoice.cancelled": "replay_invoice",
    "invoice.failed": "replay_webhook",
    "refund.created": "settle_ledger",
    "refund.updated": "escalate_queue",
    "refund.cancelled": "provision_ledger",
    "refund.failed": "escalate_ledger",
    "account.created": "flush_webhook",
    "account.updated": "void_shipment",
    "account.cancelled": "enqueue_queue",
    "account.failed": "snapshot_invoice",
}

def dispatch(event, payload):
    handler = EVENT_DISPATCH[event]   # which handler runs for this event
    return HANDLERS[handler](payload)

